package dev.johnoreilly.common.remote

import io.ktor.client.*
import io.ktor.client.call.*
import io.ktor.client.request.*
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.koin.core.annotation.Single
import org.koin.core.component.KoinComponent

@Serializable
data class AstroResult(val message: String, val number: Int, val people: List<Assignment>)

@Serializable
data class Assignment(
    val craft: String,
    val name: String,
    var personImageUrl: String? = "",
    var personBio: String? = "",
    var nationality: String = "",
)

@Serializable
data class IssPosition(val latitude: Double, val longitude: Double, val timestamp: Long  = -1)

@Serializable
data class IssResponse(val message: String, val iss_position: IssPosition, val timestamp: Long)

@Single
class PeopleInSpaceApi(private val client: HttpClient) : KoinComponent {
    var baseUrl = "https://people-in-space-proxy.ew.r.appspot.com"

    suspend fun fetchPeople() = people //client.get("$baseUrl/astros.json").body<AstroResult>()
    suspend fun fetchISSPosition() = iss //client.get("$baseUrl/iss-now.json").body<IssResponse>()
}

